import{c as t,Q as o,j as r,m as a}from"./chunks/framework.UrNQy43l.js";const g=JSON.parse('{"title":"Troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"troubleshooting.md","filePath":"troubleshooting.md"}'),d={name:"troubleshooting.md"};function c(s,e,i,n,l,h){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h1><p>datum-server exposes structured logs, health endpoints, and Prometheus metrics (see <a href="/datum/api.html#datum-server-go-binary">API Reference → datum-server</a>). This page is the practical companion: what to look at first for common problems, and what each signal actually means.</p><h2 id="start-here" tabindex="-1">Start here <a class="header-anchor" href="#start-here" aria-label="Permalink to &quot;Start here&quot;">​</a></h2><ol><li><code>curl your-server:3000/readyz</code> — is the server up and can it reach Postgres?</li><li><code>LOG_LEVEL=debug</code> — logs are JSON on stdout; every line has a <code>msg</code> field you can grep for (all message strings below are exact).</li><li><code>curl your-server:3000/metrics</code> — Prometheus metrics, safe to scrape continuously.</li></ol><h2 id="health-checks" tabindex="-1">Health checks <a class="header-anchor" href="#health-checks" aria-label="Permalink to &quot;Health checks&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Meaning</th><th>What to check</th></tr></thead><tbody><tr><td><code>/healthz</code> returns non-200 or times out</td><td>The process itself isn&#39;t serving HTTP</td><td>Is the container/process actually running? Check for a crash in the startup logs (<code>config error</code>, <code>connect to postgres failed</code>, <code>migration failed</code>, etc. — these are fatal and the process exits).</td></tr><tr><td><code>/healthz</code> is <code>200</code> but <code>/readyz</code> is <code>503</code></td><td>Process is alive, Postgres is not reachable</td><td>Check <code>DATABASE_URL</code>, network/firewall rules between datum-server and Postgres, and whether Postgres itself is up. The response body includes the underlying connection error. In Kubernetes this is normal and expected during a Postgres restart — the pod stays alive and traffic stops routing to it until <code>/readyz</code> recovers.</td></tr></tbody></table><p>Liveness and readiness are intentionally separate — see <a href="/datum/self-hosting.html#health-checks-metrics-logging">self-hosting.md</a> for why a combined check would be wrong for a WebSocket server.</p><h2 id="reading-the-logs" tabindex="-1">Reading the logs <a class="header-anchor" href="#reading-the-logs" aria-label="Permalink to &quot;Reading the logs&quot;">​</a></h2><p>Every log line is JSON with <code>component: &quot;datum-server&quot;</code>. Startup logs are fatal (the process exits after logging); everything else is &quot;log and continue.&quot; A few message strings map directly to a cause:</p><table tabindex="0"><thead><tr><th><code>msg</code></th><th>Cause</th><th>Fix</th></tr></thead><tbody><tr><td><code>missing database URL</code></td><td>Neither <code>-db</code> nor <code>DATABASE_URL</code> set</td><td>Set one of them.</td></tr><tr><td><code>connect to postgres failed</code></td><td>Can&#39;t reach Postgres at startup</td><td>Check the connection string, network, and that Postgres is running.</td></tr><tr><td><code>migration failed</code> / <code>schema introspection failed</code> / <code>column validation failed</code></td><td>The configured table doesn&#39;t match what datum-server expects</td><td>Check the <code>err</code> field — usually a missing/wrong-typed <code>id</code>, <code>updated_at</code>, or <code>geom</code> column. See <a href="/datum/api.html#datum-server-go-binary">API Reference → required columns</a>.</td></tr><tr><td><code>DATABASE_URL connects as a superuser; Row Level Security will be bypassed</code></td><td>Auth is configured but the DB role is a superuser</td><td>RLS policies are silently not enforced. Create a restricted role for production, per the warning&#39;s hint.</td></tr><tr><td><code>websocket upgrade failed</code></td><td>A client&#39;s WS handshake failed</td><td>Usually a proxy/load balancer not forwarding the Upgrade header correctly, or <code>ALLOWED_ORIGIN</code> rejecting the client&#39;s origin.</td></tr><tr><td><code>auth rejected</code> / <code>token refresh rejected</code></td><td>JWT verification failed for a client</td><td>Check the <code>err</code> field — expired token, wrong signing key/algorithm, or clock skew.</td></tr><tr><td><code>subscribe: spatial table requires a bbox</code></td><td>Client subscribed to a spatial table without a <code>bbox</code></td><td>Spatial tables always require a bbox; non-spatial tables never use one.</td></tr><tr><td><code>subscribe: invalid predicate</code></td><td>A client&#39;s <code>where</code> clause failed validation</td><td>Failed the blocklist or <code>EXPLAIN</code> syntax check — check the client&#39;s <code>where</code>/<code>whereParams</code>.</td></tr><tr><td><code>write error</code></td><td>A client&#39;s write failed to apply</td><td>Check the <code>err</code> field — commonly an invalid UUID, a type mismatch, or an RLS policy rejecting the write.</td></tr><tr><td><code>rate limit exceeded</code></td><td>A client IP hit <code>RATE_LIMIT</code></td><td>Expected under abuse or a misbehaving client; raise <code>RATE_LIMIT</code> if it&#39;s blocking legitimate traffic.</td></tr><tr><td><code>predicate check error</code> / <code>RLS check error</code></td><td>A DB error while re-checking a delta against a client&#39;s predicate/RLS</td><td>These fail open (the delta is still sent) so a transient DB error never silently drops data — but repeated errors mean something is wrong with that query; check the <code>err</code> field.</td></tr><tr><td><code>client send buffer full, dropping delta</code> / <code>... dropping gone notification</code> / <code>schema send buffer full</code> / <code>ack buffer full</code></td><td>A client&#39;s outbound buffer (64 messages) is full</td><td>The client isn&#39;t draining fast enough — usually a slow/stalled connection about to be cleaned up by the ping/pong timeout.</td></tr><tr><td><code>notify listener stopped, retrying</code></td><td>The dedicated <code>LISTEN</code> connection to Postgres dropped</td><td>Auto-retries every 5s. Frequent occurrences mean an unstable connection to Postgres.</td></tr></tbody></table><p>Every per-client log line includes <code>client_id</code>; every per-table line includes <code>table</code> — grep on those to follow one client or table across a busy log.</p><h2 id="metrics-what-to-graph" tabindex="-1">Metrics: what to graph <a class="header-anchor" href="#metrics-what-to-graph" aria-label="Permalink to &quot;Metrics: what to graph&quot;">​</a></h2><p>All metrics and labels are listed in <a href="/datum/api.html#http-endpoints">API Reference → HTTP endpoints</a>. Some starting points:</p><ul><li><strong>Connections not matching expectations</strong> — graph <code>datum_websocket_connections{table=&quot;...&quot;}</code>. If it&#39;s higher than you expect, clients aren&#39;t disconnecting cleanly (check for <code>client send buffer full</code> spam, which precedes a forced disconnect).</li><li><strong>Write failures</strong> — <code>rate(datum_writes_total{result=&quot;error&quot;}[5m])</code>. Pair with <code>write error</code> log lines (same time window) for the <code>err</code> detail.</li><li><strong>Slow snapshots</strong> — <code>histogram_quantile(0.95, rate(datum_db_query_duration_seconds_bucket{operation=&quot;snapshot&quot;}[5m]))</code>. A rising p95 usually means a missing spatial index or an overly large bbox; see <a href="/datum/self-hosting.html#postgres-postgis">self-hosting.md</a>.</li><li><strong>Unexpected rate limiting</strong> — <code>rate(datum_rate_limit_rejections_total[5m])</code>. Compare against your configured <code>RATE_LIMIT</code>.</li><li><strong>RLS/predicate check cost</strong> — <code>rate(datum_db_query_duration_seconds_sum{operation=~&quot;rls_check|predicate_check&quot;}[5m]) / rate(datum_db_query_duration_seconds_count{operation=~&quot;rls_check|predicate_check&quot;}[5m])</code> gives the average cost per delta re-check; this runs once per subscribed client per change, so it scales with (deltas × subscribers).</li></ul><h2 id="still-stuck" tabindex="-1">Still stuck? <a class="header-anchor" href="#still-stuck" aria-label="Permalink to &quot;Still stuck?&quot;">​</a></h2><p>Open an issue on <a href="https://github.com/a-saed/datum/issues" target="_blank" rel="noreferrer">GitHub</a> with your <code>datum.yaml</code> (redact secrets), the relevant log lines, and — if it&#39;s performance-related — the metrics above around the time of the problem.</p>',16)])])}const p=t(d,[["render",c]]);export{g as __pageData,p as default};
